T = typing.TypeVar('T')


def _collect(iterator: collections.abc.Iterator[T]) -> list[T]:
    """Return all items of an iterator as list."""
    return [item for item in iterator]


def _mock_client(handler: typing.Callable[[httpx2.Request], httpx2.Response]) -> Rt:
    """Return a client which sends all requests to the given handler instead of RT."""
    return Rt(url=RT_URL, client=httpx2.Client(transport=httpx2.MockTransport(handler)))


def _no_request(request: httpx2.Request) -> httpx2.Response:
    """Handler for tests which must not send any request."""
    raise AssertionError('no request must be sent')


def _small_pages_client() -> Rt:
    """Return a client requesting 2 items per page, to test results split into several pages."""
    return Rt(url=RT_URL, http_auth=httpx2.BasicAuth(RT_USER, RT_PASSWORD), http_timeout=None, per_page=2)


def _create_user(connection: Rt, **kwargs: typing.Any) -> tuple[str, int]:
    """Create a user with a random name and return its name and ID."""
    name = f'user-{random_string()}'
    connection.create_user(name, f'{name}@example.com', **kwargs)
    user = connection.get_user(name)
    return name, int(user['id'])


def _create_group(connection: Rt) -> int:
    """Create a group with a random name and return its ID."""
    return connection.create_group(f'group-{random_string()}', Description='python-rt test')


def _create_queue(connection: Rt) -> tuple[str, int]:
    """Create a queue with a random name and return its name and ID."""
    name = f'queue-{random_string()}'
    return name, connection.create_queue(name)


